package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalTwoStepTest {
 @Test public void normalNaSixSuppliesHaveAllUnitsOriginalPrecisionAndPublicTwoOperations(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(297));for(String id:List.of(DecimalTwoStepStories.REMAIN,DecimalTwoStepStories.SHARE)){assertTrue(pack.inGrade(id,6));var l=GlobalCurriculum.limits(pack.id,id,6);List<String> recent=new ArrayList<>();Set<String> units=new HashSet<>(),formats=new HashSet<>();Set<Integer> precision=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next(id,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DecimalTwoStepStories.read(q);assertNotNull(v);units.add(v.unit());formats.add(q.answerFormat);BigDecimal x=new BigDecimal(v.first()),y=new BigDecimal(v.second());precision.add(x.scale());precision.add(y.scale());Rational a=Expression.number(v.first()),b=Expression.number(v.second()),n=Rational.of(v.groups()),expected=v.remaining()?a.mul(n).sub(b):a.add(b).div(n);assertTrue(expected.compareTo(Rational.ZERO)>=0);String answer=q.answerFormat.equals("fraction")?expected.toString():(v.remaining()?x.multiply(BigDecimal.valueOf(v.groups())).subtract(y):x.add(y).divide(BigDecimal.valueOf(v.groups()))).toPlainString();q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(answer)).correct());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(q.answerFormat.equals("fraction")?12:6,h.size());assertTrue(h.step(0).accepts(v.remaining()?"mulSub":"addDiv"));assertFalse(h.step(0).accepts(v.remaining()?"addDiv":"mulSub"));}assertEquals(Set.of("m","L","kg"),units);assertEquals(Set.of(1,2,3),precision);assertEquals(id.equals(DecimalTwoStepStories.REMAIN)?Set.of("decimalValue"):Set.of("fraction","decimalValue"),formats);}}
 @Test public void exactTwoStageHelpDoesNotUseStoredKeyOrTransfer(){Question q=DecimalTwoStepStories.make(DecimalTwoStepStories.REMAIN,"1.005","0.09",3,"kg");q.answers=new String[]{"poison"};q.expression="poison";HelpPlan h=HelpPlan.forQuestion(q);List<String> entries=List.of("mulSub","1.005","0.09","3","3.015","2.925");for(int i=0;i<entries.size();i++)assertTrue(h.step(i).accepts(entries.get(i)));assertTrue(new Checker().check(q,List.of(),List.of("2.925")).correct());q=DecimalTwoStepStories.make(DecimalTwoStepStories.SHARE,"1.0","2.0",9,"L");q.answers=new String[]{"poison"};h=HelpPlan.forQuestion(q);entries=List.of("addDiv","1.0","2.0","9","3.0","1","10","30","90","30","1","3");for(int i=0;i<entries.size();i++)assertTrue(h.step(i).accepts(entries.get(i)));assertTrue(h.step(4).accepts("3"));assertTrue(h.step(5).accepts("1"));assertFalse(h.step(5).accepts("0"));assertEquals(Integer.valueOf(10),q.studyGuide.resultNumeratorFrame);assertEquals(Integer.valueOf(11),q.studyGuide.resultDenominatorFrame);assertTrue(new Checker().check(q,List.of(),List.of("1/3")).correct());assertFalse(new Checker().check(q,List.of(),List.of("0.333")).correct());q=DecimalTwoStepStories.make(DecimalTwoStepStories.SHARE,"99.9","99.9",32,"m");assertTrue(new Checker().check(q,List.of(),List.of("6.24375")).correct());assertFalse(new Checker().check(q,List.of(),List.of("6.244")).correct());}
 @Test public void fractionErrorPartComesFromPublicSumAndGroupCount(){Question q=DecimalTwoStepStories.make(DecimalTwoStepStories.SHARE,"1.0","2.0",9,"kg");q.answers=new String[]{"poison"};assertEquals(1,FractionInput.errorPart(q,"2/3"));assertEquals(2,FractionInput.errorPart(q,"1/4"));assertEquals(0,FractionInput.errorPart(q,"2/4"));assertEquals(0,FractionInput.errorPart(q,"2/6"));}
 @Test public void boundariesAndMalformedTextDoNotFallBackOrAlterLegacyPlacements(){Checker c=new Checker();Question q=DecimalTwoStepStories.make(DecimalTwoStepStories.REMAIN,"99.999","99.999",99,"m");assertTrue(c.check(q,List.of(),List.of("9799.902")).correct());q=DecimalTwoStepStories.make(DecimalTwoStepStories.REMAIN,"0.000","0.0",99,"L");assertTrue(c.check(q,List.of(),List.of("0")).correct());for(String id:List.of(DecimalTwoStepStories.REMAIN,DecimalTwoStepStories.SHARE)){assertFalse(Curriculum.inCurriculum(Catalog.get(id),2022));assertEquals(Checker.Status.INPUT_NEEDED,c.check(new Question(id,"broken","","0"),List.of(),List.of("0")).status);}try{DecimalTwoStepStories.make(DecimalTwoStepStories.REMAIN,"0.1","1.0",2,"kg");fail();}catch(IllegalArgumentException expected){}try{DecimalTwoStepStories.make(DecimalTwoStepStories.SHARE,"1.0","2.0",0,"L");fail();}catch(IllegalArgumentException expected){}assertEquals(2,GlobalCurriculum.limits("england-primary-2021-v1",DecimalMeasureStories.ADD,4).decimalPlaces(3));}
}
